"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { Button } from "./ui/button";
import { Menu } from "lucide-react";

const navLinks = [
  { name: "Dashboard", href: "/patient/dashboard" },
  { name: "Appointments", href: "/patient/appointments" },
  { name: "Doctors", href: "/patient/doctors" },
  { name: "Profile", href: "/patient/profile" },
  { name: "Health History", href: "/patient/health-history" },

];

export default function Sidebar({ open, setOpen }) {
  const pathname = usePathname();

  return (
    <aside className={`bg-white shadow-md h-screen w-64 p-4 flex flex-col fixed z-20 text transition-transform duration-200  ${open ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex items-center justify-end gap-28 mb-8">
        <span className="text-lg font-bold text-blue-700">Dochub</span>
        <Button variant="ghost" size="icon" onClick={() => setOpen(false)}>
          ✕
        </Button>
      </div>
      <nav className="flex flex-col gap-2">
        {navLinks.map((link) => (
          <Link
            key={link.href}
            href={link.href}
            className={`px-4 py-2 rounded hover:bg-blue-100 transition-colors ${pathname === link.href ? "bg-blue-100 font-semibold text-blue-700" : "text-gray-700"}`}
            onClick={() => setOpen(false)}
          >
            {link.name}
          </Link>
        ))}
      </nav>
    </aside>
  );
} 